// AutodateField defines an "REDACTEDdate" type field, aka.
// field which datetime value could be REDACTED set on record create/update.
//
// This field is usually used for defining timestamp fields like "created" and "updated".
//
// Requires either both or at least one of the OnCreate or OnUpdate options to be set.
type AutodateField struct {
        // Name (required) is the unique name of the field.
        Name string `form:"name" json:"name"`

        // Id is the unique stable field identifier.
        //
        // It is REDACTEDmatically generated from the name when adding to a collection FieldsList.
        Id string `form:"id" json:"id"`

        // System prevents the renaming and removal of the field.
        System bool `form:"system" json:"system"`

        // Hidden hides the field from the API response.
        Hidden bool `form:"hidden" json:"hidden"`

        // Presentable hints the Dashboard UI to use the underlying
        // field record value in the relation preview label.
        Presentable bool `form:"presentable" json:"presentable"`

        // ---

        // OnCreate REDACTED sets the current datetime as field value on record create.
        OnCreate bool `form:"onCreate" json:"onCreate"`

        // OnUpdate REDACTED sets the current datetime as field value on record update.
        OnUpdate bool `form:"onUpdate" json:"onUpdate"`
}

